/*
 * iceoryx2_generator.cpp - DEL Bridge Code Generator
 *
 * Part of the Data Exchange Layer (DEL) for OpenPLC v3.
 *
 * Reads LOCATED_VARIABLES.h (generated by MatIEC) and produces:
 *   1. iceoryx2_structs.h  - POD structs for each PUBLISH/SUBSCRIBE group
 *   2. iceoryx2_bridge.h   - Public C interface (init/shutdown/publish/subscribe)
 *   3. iceoryx2_bridge.cpp - Implementation using del_iox_wrapper API
 *
 * Input format (extended __LOCATED_VAR macro):
 *   __LOCATED_VAR(INT,__QW0,Q,W,0)                    -- normal (ignored)
 *   __LOCATED_VAR(INT,__QW0,Q,W,0,PUBLISH,Motors)      -- publish group
 *   __LOCATED_VAR(INT,__IW10,I,W,10,SUBSCRIBE,CANBus)  -- subscribe group
 *   __LOCATED_VAR(BOOL,__QX0_0,Q,X,0,0,PUBLISH,Motors) -- bool with bit addr
 *
 * The extra PUBLISH/SUBSCRIBE + group_name parameters are appended by the
 * extended MatIEC code generator and silently ignored by the existing
 * glue_generator (which uses variadic ...).
 *
 * Copyright (C) 2025 OpenPLC DEL Contributors
 * Licensed under GPL v3 (same as OpenPLC v3)
 */

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <cstring>
#include <cstdlib>
#include <sstream>
#include <algorithm>
#include <cctype>

using namespace std;

/* ------------------------------------------------------------------ */
/*  Configuration                                                      */
/* ------------------------------------------------------------------ */

#define IOX_MAX_GROUPS    16
#define IOX_MAX_FIELDS    32
#define IOX_MAX_NAME_LEN  64

/* ------------------------------------------------------------------ */
/*  Data Structures                                                    */
/* ------------------------------------------------------------------ */

struct IecVar {
    string iecType;      /* IEC type: INT, BOOL, DINT, ... */
    string varName;      /* Variable name from macro: "__QW0" */
    string fieldName;    /* Struct field name: "QW0", "QX0_0" */
    string iecAddress;   /* IEC address: "%QW0", "%QX0.0" */
    string cType;        /* C type: int16_t, uint8_t, ... */
    int    byteSize;     /* Size in bytes */
};

struct IoxGroup {
    string name;         /* Group name, e.g. "Motors" */
    string safeName;     /* C-safe identifier, e.g. "Motors" */
    string direction;    /* "PUBLISH" or "SUBSCRIBE" */
    vector<IecVar> vars;
};

/* ------------------------------------------------------------------ */
/*  Helper Functions                                                   */
/* ------------------------------------------------------------------ */

static string trim(const string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

static string stripQuotes(const string& s) {
    string t = trim(s);
    if (t.size() >= 2 && t.front() == '\'' && t.back() == '\'')
        return t.substr(1, t.size() - 2);
    if (t.size() >= 2 && t.front() == '"' && t.back() == '"')
        return t.substr(1, t.size() - 2);
    return t;
}

/* Make a string safe for use as a C identifier */
static string sanitizeIdent(const string& name) {
    string r;
    for (char c : name) {
        if (isalnum((unsigned char)c) || c == '_')
            r += c;
        else
            r += '_';
    }
    if (!r.empty() && isdigit((unsigned char)r[0]))
        r = "_" + r;
    return r;
}

/* IEC type -> C99 fixed-width type */
static string iecToCType(const string& t) {
    if (t == "BOOL")  return "uint8_t";
    if (t == "BYTE")  return "uint8_t";
    if (t == "SINT")  return "int8_t";
    if (t == "USINT") return "uint8_t";
    if (t == "INT")   return "int16_t";
    if (t == "UINT")  return "uint16_t";
    if (t == "WORD")  return "uint16_t";
    if (t == "DINT")  return "int32_t";
    if (t == "UDINT") return "uint32_t";
    if (t == "DWORD") return "uint32_t";
    if (t == "LINT")  return "int64_t";
    if (t == "ULINT") return "uint64_t";
    if (t == "LWORD") return "uint64_t";
    if (t == "REAL")  return "float";
    if (t == "LREAL") return "double";
    cerr << "Warning: unknown IEC type '" << t << "', defaulting to uint8_t" << endl;
    return "uint8_t";
}

/* IEC type -> byte size */
static int iecTypeSize(const string& t) {
    if (t == "BOOL" || t == "BYTE" || t == "SINT" || t == "USINT") return 1;
    if (t == "INT"  || t == "UINT" || t == "WORD")                 return 2;
    if (t == "DINT" || t == "UDINT"|| t == "DWORD"|| t == "REAL")  return 4;
    if (t == "LINT" || t == "ULINT"|| t == "LWORD"|| t == "LREAL") return 8;
    return 1;
}

/* "__QW0" -> "QW0",  "__IX0_0" -> "QX0_0" */
static string varToField(const string& v) {
    if (v.size() > 2 && v[0] == '_' && v[1] == '_')
        return v.substr(2);
    return v;
}

/* "__QW0" -> "%QW0",  "__IX0_0" -> "%IX0.0" */
static string varToIecAddr(const string& v) {
    string f = varToField(v);
    string a = "%" + f;
    /* Bit addressing: QX0_0 -> %QX0.0 */
    if (f.size() > 1 && f[1] == 'X') {
        size_t p = a.find('_');
        if (p != string::npos) a[p] = '.';
    }
    return a;
}

/* Compute total packed struct size for a group */
static int groupStructSize(const IoxGroup& g) {
    int sz = 0;
    for (const auto& v : g.vars) sz += v.byteSize;
    return sz;
}

/* ------------------------------------------------------------------ */
/*  Parsing                                                            */
/* ------------------------------------------------------------------ */

/* Split __LOCATED_VAR(a, b, c, ...) into individual tokens */
static vector<string> splitMacroParams(const string& line) {
    vector<string> params;
    int depth = 0;
    string cur;

    for (char c : line) {
        if (c == '(') {
            depth++;
            if (depth == 1) continue; /* skip outermost '(' */
        } else if (c == ')') {
            depth--;
            if (depth == 0) {
                params.push_back(trim(cur));
                break;
            }
        }
        if (depth >= 1) {
            if (c == ',' && depth == 1) {
                params.push_back(trim(cur));
                cur.clear();
            } else {
                cur += c;
            }
        }
    }
    return params;
}

/*
 * Parse LOCATED_VARIABLES.h and return groups keyed by "DIRECTION:name".
 * Variables without PUBLISH/SUBSCRIBE metadata are silently skipped.
 */
static map<string, IoxGroup> parseLocatedVars(istream& in) {
    map<string, IoxGroup> groups;
    string line;

    while (getline(in, line)) {
        if (line.find("__LOCATED_VAR") == string::npos) continue;

        vector<string> p = splitMacroParams(line);
        if (p.size() < 5) continue; /* minimum: type, name, dir, size, addr */

        /* Scan for PUBLISH or SUBSCRIBE token */
        string ioxDir, ioxGroup;
        for (size_t i = 2; i < p.size(); i++) {
            if (p[i] == "PUBLISH" || p[i] == "SUBSCRIBE") {
                ioxDir = p[i];
                if (i + 1 < p.size())
                    ioxGroup = stripQuotes(p[i + 1]);
                break;
            }
        }
        if (ioxDir.empty() || ioxGroup.empty()) continue;

        /* Build variable descriptor */
        IecVar var;
        var.iecType    = p[0];
        var.varName    = p[1];
        var.fieldName  = varToField(var.varName);
        var.iecAddress = varToIecAddr(var.varName);
        var.cType      = iecToCType(var.iecType);
        var.byteSize   = iecTypeSize(var.iecType);

        /* Insert into group */
        string key = ioxDir + ":" + ioxGroup;
        if (groups.find(key) == groups.end()) {
            IoxGroup g;
            g.name      = ioxGroup;
            g.safeName  = sanitizeIdent(ioxGroup);
            g.direction = ioxDir;
            groups[key] = g;
        }
        groups[key].vars.push_back(var);

        cout << "  " << ioxDir << " '" << ioxGroup << "': "
             << var.iecType << " " << var.varName
             << " (" << var.cType << ", " << var.byteSize << "B)" << endl;
    }
    return groups;
}

/* ------------------------------------------------------------------ */
/*  Code Generation: iceoryx2_structs.h                                */
/* ------------------------------------------------------------------ */

static void genStructsHeader(ostream& out, map<string, IoxGroup>& groups) {
    out << "/* Auto-generated by iceoryx2_generator - DO NOT EDIT */\n";
    out << "/* Part of the Data Exchange Layer (DEL) for OpenPLC v3 */\n";
    out << "#ifndef ICEORYX2_STRUCTS_H\n";
    out << "#define ICEORYX2_STRUCTS_H\n\n";
    out << "#include <stdint.h>\n";
    out << "#include <stddef.h>\n\n";

    /* ---- Descriptor structs (fixed layout for runtime discovery) ---- */
    out << "/* ---- Descriptor structs for runtime discovery ---- */\n\n";
    out << "#define IOX_MAX_GROUPS    " << IOX_MAX_GROUPS << "\n";
    out << "#define IOX_MAX_FIELDS    " << IOX_MAX_FIELDS << "\n";
    out << "#define IOX_MAX_NAME_LEN  " << IOX_MAX_NAME_LEN << "\n\n";

    out << "struct IoxFieldDescriptor {\n";
    out << "    char     name[IOX_MAX_NAME_LEN];\n";
    out << "    char     iec_type[16];\n";
    out << "    char     iec_address[16];\n";
    out << "    uint16_t offset;\n";
    out << "    uint16_t size;\n";
    out << "} __attribute__((packed));\n\n";

    out << "struct IoxGroupDescriptor {\n";
    out << "    char     name[IOX_MAX_NAME_LEN];\n";
    out << "    char     service_name[IOX_MAX_NAME_LEN];\n";
    out << "    char     direction[12];\n";
    out << "    uint16_t field_count;\n";
    out << "    uint16_t struct_size;\n";
    out << "    struct IoxFieldDescriptor fields[IOX_MAX_FIELDS];\n";
    out << "} __attribute__((packed));\n\n";

    out << "struct IoxDescriptor {\n";
    out << "    uint32_t version;\n";
    out << "    uint32_t group_count;\n";
    out << "    uint32_t cycle_time_us;\n";
    out << "    char     program_name[IOX_MAX_NAME_LEN];\n";
    out << "    struct IoxGroupDescriptor groups[IOX_MAX_GROUPS];\n";
    out << "} __attribute__((packed));\n\n";

    /* ---- Per-group data structs ---- */
    out << "/* ---- Data structs per IceOryx2 group ---- */\n\n";

    for (auto& kv : groups) {
        IoxGroup& g = kv.second;
        out << "/* " << g.direction << " group '" << g.name << "' */\n";
        out << "struct IoxGroup_" << g.safeName << " {\n";
        for (const auto& v : g.vars) {
            out << "    " << v.cType << " " << v.fieldName << ";";
            out << "  /* " << v.iecType << " " << v.iecAddress << " */\n";
        }
        out << "} __attribute__((packed));\n\n";
    }

    out << "#endif /* ICEORYX2_STRUCTS_H */\n";
}

/* ------------------------------------------------------------------ */
/*  Code Generation: iceoryx2_bridge.h                                 */
/* ------------------------------------------------------------------ */

static void genBridgeHeader(ostream& out) {
    out << "/* Auto-generated by iceoryx2_generator - DO NOT EDIT */\n";
    out << "/* Part of the Data Exchange Layer (DEL) for OpenPLC v3 */\n";
    out << "#ifndef ICEORYX2_BRIDGE_H\n";
    out << "#define ICEORYX2_BRIDGE_H\n\n";
    out << "#ifdef __cplusplus\n";
    out << "extern \"C\" {\n";
    out << "#endif\n\n";
    out << "/* Initialize IceOryx2 node, create publishers/subscribers,\n";
    out << " * and publish the descriptor topic. Returns 0 on success. */\n";
    out << "int  iceoryx2_init(void);\n\n";
    out << "/* Shut down IceOryx2 and release all resources. */\n";
    out << "void iceoryx2_shutdown(void);\n\n";
    out << "/* Publish all PUBLISH groups. Call AFTER PLC logic cycle. */\n";
    out << "void iceoryx2_publish_all(void);\n\n";
    out << "/* Receive all SUBSCRIBE groups. Call BEFORE PLC logic cycle. */\n";
    out << "void iceoryx2_subscribe_all(void);\n\n";
    out << "#ifdef __cplusplus\n";
    out << "}\n";
    out << "#endif\n\n";
    out << "#endif /* ICEORYX2_BRIDGE_H */\n";
}

/* ------------------------------------------------------------------ */
/*  Code Generation: iceoryx2_bridge.cpp                               */
/* ------------------------------------------------------------------ */

static void genBridgeImpl(ostream& out, map<string, IoxGroup>& groups) {
    /* Separate by direction */
    vector<IoxGroup*> pubs, subs;
    for (auto& kv : groups) {
        if (kv.second.direction == "PUBLISH")
            pubs.push_back(&kv.second);
        else
            subs.push_back(&kv.second);
    }

    out << "/* Auto-generated by iceoryx2_generator - DO NOT EDIT */\n";
    out << "/* Part of the Data Exchange Layer (DEL) for OpenPLC v3 */\n\n";
    out << "#include <cstring>\n";
    out << "#include <cstdio>\n";
    out << "#include \"iceoryx2_structs.h\"\n";
    out << "#include \"iceoryx2_bridge.h\"\n";
    out << "#include \"del_iox_wrapper.h\"\n\n";

    /* Access to located PLC variables (pointers defined in glueVars.cpp) */
    out << "/* Access PLC located variables (defined in glueVars.cpp) */\n";
    out << "extern \"C\" {\n";
    out << "#define __LOCATED_VAR(type, name, ...) extern type *name;\n";
    out << "#include \"LOCATED_VARIABLES.h\"\n";
    out << "#undef __LOCATED_VAR\n";
    out << "}\n\n";

    /* Cycle time from IEC runtime */
    out << "extern unsigned long long common_ticktime__;\n\n";

    /* ---- Static handles ---- */
    out << "/* ---- Static handles ---- */\n";
    out << "static del_node_t iox_node = NULL;\n";
    out << "static del_pub_t  iox_pub_descriptor = NULL;\n\n";

    for (auto* g : pubs)
        out << "static del_pub_t  iox_pub_" << g->safeName << " = NULL;\n";
    for (auto* g : subs)
        out << "static del_sub_t  iox_sub_" << g->safeName << " = NULL;\n";
    out << "\n";

    /* ---- Pre-filled descriptor ---- */
    out << "/* ---- Descriptor (fields populated at compile time) ---- */\n";
    out << "static struct IoxDescriptor iox_descriptor = {\n";
    out << "    1,  /* version */\n";
    out << "    " << groups.size() << ",  /* group_count */\n";
    out << "    0,  /* cycle_time_us - filled at runtime */\n";
    out << "    \"\", /* program_name  - filled at runtime */\n";
    out << "    {   /* groups[] */\n";

    int gIdx = 0;
    for (auto& kv : groups) {
        IoxGroup& g = kv.second;
        int sSize = groupStructSize(g);
        string svcName = "OpenPLC/" + g.name;

        out << "        { /* [" << gIdx << "] " << g.direction
            << " '" << g.name << "' */\n";
        out << "            \"" << g.name << "\",  /* name */\n";
        out << "            \"" << svcName << "\",  /* service_name */\n";
        out << "            \"" << g.direction << "\",  /* direction */\n";
        out << "            " << g.vars.size() << ",  /* field_count */\n";
        out << "            " << sSize << ",  /* struct_size */\n";
        out << "            {  /* fields[] */\n";

        int offset = 0;
        for (size_t f = 0; f < g.vars.size(); f++) {
            const IecVar& v = g.vars[f];
            out << "                { \"" << v.fieldName << "\", \""
                << v.iecType << "\", \"" << v.iecAddress << "\", "
                << offset << ", " << v.byteSize << " }";
            if (f + 1 < g.vars.size()) out << ",";
            out << "\n";
            offset += v.byteSize;
        }

        out << "            }\n";
        out << "        }";
        if (gIdx + 1 < (int)groups.size()) out << ",";
        out << "\n";
        gIdx++;
    }

    out << "    }\n";
    out << "};\n\n";

    /* ================================================================ */
    /*  iceoryx2_init                                                    */
    /* ================================================================ */
    out << "/* ================================================================ */\n";
    out << "/*  Initialization                                                  */\n";
    out << "/* ================================================================ */\n\n";
    out << "int iceoryx2_init(void) {\n";
    out << "    printf(\"DEL: Initializing IceOryx2 bridge...\\n\");\n\n";

    out << "    /* Fill runtime descriptor fields */\n";
    out << "    iox_descriptor.cycle_time_us = (uint32_t)(common_ticktime__ / 1000ULL);\n\n";

    out << "    /* Create IceOryx2 node */\n";
    out << "    iox_node = del_node_create(\"OpenPLC\");\n";
    out << "    if (!iox_node) {\n";
    out << "        printf(\"DEL: ERROR - Failed to create IceOryx2 node\\n\");\n";
    out << "        return -1;\n";
    out << "    }\n\n";

    /* Create publishers */
    for (auto* g : pubs) {
        int sz = groupStructSize(*g);
        string svcName = "OpenPLC/" + g->name;
        out << "    /* Publisher: " << g->name << " (" << sz << " bytes) */\n";
        out << "    iox_pub_" << g->safeName
            << " = del_pub_create(iox_node, \"" << svcName << "\", "
            << "sizeof(struct IoxGroup_" << g->safeName << "));\n";
        out << "    if (iox_pub_" << g->safeName << ")\n";
        out << "        printf(\"DEL: Publisher '%s' ready (%d bytes)\\n\", \""
            << g->name << "\", " << sz << ");\n\n";
    }

    /* Create subscribers */
    for (auto* g : subs) {
        int sz = groupStructSize(*g);
        string svcName = "OpenPLC/" + g->name;
        out << "    /* Subscriber: " << g->name << " (" << sz << " bytes) */\n";
        out << "    iox_sub_" << g->safeName
            << " = del_sub_create(iox_node, \"" << svcName << "\", "
            << "sizeof(struct IoxGroup_" << g->safeName << "));\n";
        out << "    if (iox_sub_" << g->safeName << ")\n";
        out << "        printf(\"DEL: Subscriber '%s' ready (%d bytes)\\n\", \""
            << g->name << "\", " << sz << ");\n\n";
    }

    /* Publish descriptor */
    out << "    /* Publish descriptor topic */\n";
    out << "    iox_pub_descriptor = del_pub_create(iox_node, \"OpenPLC/Descriptor\", "
        << "sizeof(struct IoxDescriptor));\n";
    out << "    if (iox_pub_descriptor) {\n";
    out << "        del_publish(iox_pub_descriptor, &iox_descriptor, sizeof(iox_descriptor));\n";
    out << "        printf(\"DEL: Descriptor published (%u groups)\\n\", iox_descriptor.group_count);\n";
    out << "    }\n\n";

    out << "    printf(\"DEL: IceOryx2 bridge initialized ("
        << pubs.size() << " pub, " << subs.size() << " sub)\\n\");\n";
    out << "    return 0;\n";
    out << "}\n\n";

    /* ================================================================ */
    /*  iceoryx2_shutdown                                                */
    /* ================================================================ */
    out << "/* ================================================================ */\n";
    out << "/*  Shutdown                                                        */\n";
    out << "/* ================================================================ */\n\n";
    out << "void iceoryx2_shutdown(void) {\n";
    out << "    printf(\"DEL: Shutting down IceOryx2 bridge...\\n\");\n";

    for (auto* g : pubs)
        out << "    if (iox_pub_" << g->safeName << ") del_pub_destroy(iox_pub_"
            << g->safeName << ");\n";
    for (auto* g : subs)
        out << "    if (iox_sub_" << g->safeName << ") del_sub_destroy(iox_sub_"
            << g->safeName << ");\n";

    out << "    if (iox_pub_descriptor) del_pub_destroy(iox_pub_descriptor);\n";
    out << "    if (iox_node) del_node_destroy(iox_node);\n";
    out << "    iox_node = NULL;\n";
    out << "    printf(\"DEL: IceOryx2 bridge shut down\\n\");\n";
    out << "}\n\n";

    /* ================================================================ */
    /*  iceoryx2_publish_all                                             */
    /* ================================================================ */
    out << "/* ================================================================ */\n";
    out << "/*  Publish all PUBLISH groups                                      */\n";
    out << "/* ================================================================ */\n\n";
    out << "void iceoryx2_publish_all(void) {\n";

    if (pubs.empty()) {
        out << "    /* No PUBLISH groups configured */\n";
    }

    for (auto* g : pubs) {
        out << "    /* Group: " << g->name << " */\n";
        out << "    if (iox_pub_" << g->safeName << ") {\n";
        out << "        struct IoxGroup_" << g->safeName << " data;\n";
        out << "        memset(&data, 0, sizeof(data));\n";

        for (const auto& v : g->vars) {
            out << "        if (" << v.varName << ") data."
                << v.fieldName << " = (" << v.cType << ")*"
                << v.varName << ";\n";
        }

        out << "        del_publish(iox_pub_" << g->safeName
            << ", &data, sizeof(data));\n";
        out << "    }\n\n";
    }

    out << "}\n\n";

    /* ================================================================ */
    /*  iceoryx2_subscribe_all                                           */
    /* ================================================================ */
    out << "/* ================================================================ */\n";
    out << "/*  Receive all SUBSCRIBE groups                                    */\n";
    out << "/* ================================================================ */\n\n";
    out << "void iceoryx2_subscribe_all(void) {\n";

    if (subs.empty()) {
        out << "    /* No SUBSCRIBE groups configured */\n";
    }

    for (auto* g : subs) {
        out << "    /* Group: " << g->name << " */\n";
        out << "    if (iox_sub_" << g->safeName << ") {\n";
        out << "        struct IoxGroup_" << g->safeName << " data;\n";
        out << "        if (del_receive(iox_sub_" << g->safeName
            << ", &data, sizeof(data)) == 0) {\n";

        for (const auto& v : g->vars) {
            out << "            if (" << v.varName << ") *"
                << v.varName << " = (" << v.iecType << ")data."
                << v.fieldName << ";\n";
        }

        out << "        }\n";
        out << "    }\n\n";
    }

    out << "}\n";
}

/* ------------------------------------------------------------------ */
/*  Stub Generation (no PUBLISH/SUBSCRIBE variables)                   */
/* ------------------------------------------------------------------ */

static void genStubs(const string& dir) {
    cout << "No PUBLISH/SUBSCRIBE variables found - generating stubs." << endl;

    /* Empty structs header */
    {
        ofstream f(dir + "/iceoryx2_structs.h", ios::trunc);
        f << "/* Auto-generated stub - no PUBLISH/SUBSCRIBE variables */\n";
        f << "#ifndef ICEORYX2_STRUCTS_H\n";
        f << "#define ICEORYX2_STRUCTS_H\n";
        f << "#endif\n";
    }

    /* Bridge header (always the same) */
    {
        ofstream f(dir + "/iceoryx2_bridge.h", ios::trunc);
        genBridgeHeader(f);
    }

    /* Stub implementation - no IceOryx2 dependency */
    {
        ofstream f(dir + "/iceoryx2_bridge.cpp", ios::trunc);
        f << "/* Auto-generated stub - no PUBLISH/SUBSCRIBE variables */\n";
        f << "#include \"iceoryx2_bridge.h\"\n";
        f << "#include <cstdio>\n\n";
        f << "int  iceoryx2_init(void)         { printf(\"DEL: No IceOryx2 groups configured\\n\"); return 0; }\n";
        f << "void iceoryx2_shutdown(void)      { }\n";
        f << "void iceoryx2_publish_all(void)   { }\n";
        f << "void iceoryx2_subscribe_all(void) { }\n";
    }
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[]) {
    cout << "=== IceOryx2 Bridge Generator (DEL) ===" << endl;

    /* Parse arguments */
    string inputFile = "LOCATED_VARIABLES.h";
    string outputDir = ".";

    if (argc >= 2) {
        string a = argv[1];
        if (a == "-h" || a == "--help") {
            cout << "Usage: iceoryx2_generator [input] [output_dir]\n"
                 << "  input      Path to LOCATED_VARIABLES.h (default: ./LOCATED_VARIABLES.h)\n"
                 << "  output_dir Directory for generated files (default: .)\n"
                 << "\nReads the extended __LOCATED_VAR macros produced by MatIEC and\n"
                 << "generates IceOryx2 bridge code for the DEL.\n";
            return 0;
        }
        inputFile = a;
    }
    if (argc >= 3) {
        outputDir = argv[2];
    }

    /* Open input */
    ifstream input(inputFile, ios::in);
    if (!input.is_open()) {
        cerr << "Error: Cannot open " << inputFile << endl;
        return 1;
    }

    cout << "Reading " << inputFile << " ..." << endl;

    /* Parse */
    map<string, IoxGroup> groups = parseLocatedVars(input);
    input.close();

    /* No iceoryx groups -> generate stubs */
    if (groups.empty()) {
        genStubs(outputDir);
        cout << "=== Stub generation complete ===" << endl;
        return 0;
    }

    cout << "Found " << groups.size() << " IceOryx2 group(s)" << endl;

    /* Validate limits */
    if (groups.size() > IOX_MAX_GROUPS) {
        cerr << "Error: Too many groups (" << groups.size()
             << " > " << IOX_MAX_GROUPS << ")" << endl;
        return 3;
    }
    for (auto& kv : groups) {
        if (kv.second.vars.size() > IOX_MAX_FIELDS) {
            cerr << "Error: Group '" << kv.second.name << "' has too many fields ("
                 << kv.second.vars.size() << " > " << IOX_MAX_FIELDS << ")" << endl;
            return 3;
        }
    }

    /* Generate output files */
    string fStructs = outputDir + "/iceoryx2_structs.h";
    string fBridgeH = outputDir + "/iceoryx2_bridge.h";
    string fBridgeC = outputDir + "/iceoryx2_bridge.cpp";

    {
        ofstream f(fStructs, ios::trunc);
        if (!f.is_open()) { cerr << "Error: Cannot write " << fStructs << endl; return 2; }
        genStructsHeader(f, groups);
        cout << "Generated " << fStructs << endl;
    }
    {
        ofstream f(fBridgeH, ios::trunc);
        if (!f.is_open()) { cerr << "Error: Cannot write " << fBridgeH << endl; return 2; }
        genBridgeHeader(f);
        cout << "Generated " << fBridgeH << endl;
    }
    {
        ofstream f(fBridgeC, ios::trunc);
        if (!f.is_open()) { cerr << "Error: Cannot write " << fBridgeC << endl; return 2; }
        genBridgeImpl(f, groups);
        cout << "Generated " << fBridgeC << endl;
    }

    cout << "=== Generation complete ===" << endl;
    return 0;
}
